using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using Vortice.Direct3D11;

namespace YuCap;

/// <summary>
/// 「ぼやけを取ってから拡大」: the Anime4K Restore CNN (bloc97, MIT; third_party/Anime4K, generated by tools/a4k_gen.py) as a pre-pass in front of
/// the scaler. It removes blur and some compression softness at the picture's own size (no scaling), and its result is what FSR / the
/// Anime4K upscaler then enlarge. Cached per picture like the upscaler's own result.
/// </summary>
internal sealed partial class D3DRenderer
{
    /// <summary>Anime4K Restore network: 'S', 'M' or 'L'.</summary>
    public static char RestoreVariantLetter = 'S';
    /// <summary>0 off (the default), 1 on: FSR and くっきり enlarge the restored picture. Not used while 元の細かさに合わせて拡大 shrinks the picture
    /// first (measured worse: the shrink already removes the blur the network would remove).</summary>
    public static int RestoreMode;
    /// <summary>Test hook: restore for every scaled draw regardless of <see cref="RestoreMode"/>.</summary>
    public static bool RestoreForce;

    internal readonly record struct RestoreKey(long Ver, int PreH, int PreFilter, int PreIter, float PreClamp, char Variant, bool Half);

    private readonly List<A4kTex?> _restInter = new();
    private A4kTex? _restOut;
    private RestoreKey _restKey;
    private bool _restHaveKey, _restBroken;
    private ID3D11PixelShader[]? _restPs;
    private char _restPsLetter;

    private static A4kPassInfo[] RestorePassesOf(char v) => v switch { 'S' => A4kModels.RestorePassesS, 'L' => A4kModels.RestorePassesL, _ => A4kModels.RestorePassesM };
    private static int RestoreTexturesOf(char v) => v switch { 'S' => A4kModels.RestoreTexturesS, 'L' => A4kModels.RestoreTexturesL, _ => A4kModels.RestoreTexturesM };

    /// <summary>The restore pre-pass applies to this draw (<paramref name="shrunk"/>: the picture is first shrunk to its real detail).</summary>
    private bool RestoreWanted(ScalingQuality quality, bool shrunk)
    {
        if (_restBroken || GuardNoRestore) return false;
        if (RestoreForce) return quality != ScalingQuality.Standard;
        return RestoreMode == 1 && quality != ScalingQuality.Standard && !shrunk;
    }

    private bool EnsureRestoreShaders()
    {
        char v = RestoreVariantLetter;
        if (_restPs != null && _restPsLetter == v) return true;
        byte[][] code = D3DShaders.GetRestore(v);
        if (_restPs != null) foreach (var p in _restPs) p.Dispose();
        _restPs = new ID3D11PixelShader[code.Length];
        for (int i = 0; i < code.Length; i++) _restPs[i] = Device.CreatePixelShader(code[i]);
        _restPsLetter = v;
        _cbA4k ??= Device.CreateBuffer(new BufferDescription(16, BindFlags.ConstantBuffer, ResourceUsage.Default));
        return true;
    }

    /// <summary>Run the Restore network on <paramref name="input"/> (size <paramref name="src"/>); the result (same size) lands in _restOut.</summary>
    private bool RestoreRun(ID3D11ShaderResourceView input, Size src, RestoreKey key)
    {
        try
        {
            if (!EnsureRestoreShaders()) return false;
            A4kPassInfo[] passes = RestorePassesOf(_restPsLetter);
            int nTex = RestoreTexturesOf(_restPsLetter);
            while (_restInter.Count < nTex) _restInter.Add(null);
            for (int i = 0; i < nTex; i++) { A4kTex? t = _restInter[i]; A4kEnsure(ref t, src); _restInter[i] = t; }
            A4kTex outTex = A4kEnsure(ref _restOut, src);
            WriteCb(_cbA4k!, new uint[] { (uint)src.Width, (uint)src.Height, 0, 0 });
            for (int pi = 0; pi < passes.Length; pi++)
            {
                A4kPassInfo p = passes[pi];
                A4kTex target = p.Output == -2 ? outTex : _restInter[p.Output]!;
                SetupTriangle(target.Rtv, new Rectangle(0, 0, target.Size.Width, target.Size.Height));
                Ctx.PSSetShader(_restPs![pi]);
                Ctx.PSSetConstantBuffer(0, _cbA4k);
                Ctx.PSSetSampler(0, _linear);
                for (int k = 0; k < p.Inputs.Length; k++)
                    Ctx.PSSetShaderResource((uint)k, p.Inputs[k] < 0 ? input : _restInter[p.Inputs[k]]!.Srv);
                Ctx.Draw(3, 0);
                for (int k = 0; k < p.Inputs.Length; k++) Ctx.PSSetShaderResource((uint)k, null!);
            }
            _restKey = key; _restHaveKey = true;
            return true;
        }
        catch (Exception ex)
        {
            Log.Info("D3D: Anime4K Restore failed - " + ex.Message.Split('\n')[0]);
            _restBroken = true; _restHaveKey = false;
            return false;
        }
    }

    private void RestoreFree()
    {
        foreach (var t in _restInter) t?.Dispose();
        _restInter.Clear();
        _restOut?.Dispose(); _restOut = null; _restHaveKey = false;
        if (_restPs != null) { foreach (var p in _restPs) p.Dispose(); _restPs = null; }
    }

    /// <summary>Test hook: the Restore network alone on <paramref name="src"/> (as the oriented picture), read back as float RGBA.</summary>
    internal float[]? RestoreReadRaw(Bitmap src, out Size size)
    {
        size = Size.Empty;
        lock (FrameLock)
        {
            EnsureOriented(src.Size);
            BitmapData bd = src.LockBits(new Rectangle(Point.Empty, src.Size), ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb);
            try { Ctx.UpdateSubresource(_oriented!, 0, null, bd.Scan0, (uint)bd.Stride, 0); _orientedVer++; }
            finally { src.UnlockBits(bd); }
            if (!RestoreRun(_orientedSrv!, src.Size, new RestoreKey(_orientedVer, 0, 0, 0, 0f, RestoreVariantLetter, A4kHalf))) return null;
            Ctx.OMSetRenderTargets(Array.Empty<ID3D11RenderTargetView>());
            size = _restOut!.Size;
            return ReadFloats(_restOut);
        }
    }

    /// <summary>Test hook: make <paramref name="src"/> the oriented picture (for <see cref="RestoreBench"/>).</summary>
    internal void RestoreBenchSetup(Bitmap src)
    {
        lock (FrameLock)
        {
            EnsureOriented(src.Size);
            BitmapData bd = src.LockBits(new Rectangle(Point.Empty, src.Size), ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb);
            try { Ctx.UpdateSubresource(_oriented!, 0, null, bd.Scan0, (uint)bd.Stride, 0); _orientedVer++; }
            finally { src.UnlockBits(bd); }
        }
    }

    /// <summary>GPU milliseconds of the Restore pass alone for a picture of <paramref name="src"/> (the oriented picture given earlier).</summary>
    internal double[] RestoreBench(Size src, int frames)
    {
        if (_oriented == null) return Array.Empty<double>();
        try { return TimeGpu(() => RestoreRun(_orientedSrv!, src, new RestoreKey(-1, 0, 0, 0, 0f, RestoreVariantLetter, A4kHalf)), frames); }
        finally { Ctx.OMSetRenderTargets(Array.Empty<ID3D11RenderTargetView>()); }
    }
}
